//! A device output's name → whether ngspice-45 has a vector for it: `@dev[name]` reads only
//! the rows of the device's instance table that are readable (`OP`, `IOP`), from
//! `families/outputs.txt`, generated by `families/outputs.py` from the ngspice-45 source. The
//! device is the card letter's (every device an `M` card may run, for instance); a letter with
//! no table here (X, A, N) is not judged.
//!
//! Cites: ngspice-45 `src/spicelib/devices/*/*.c` (`*pTable`); runs, settle `device_outputs.sp`
//! (`@i1[c]`, `@i1[current]`, `@r1[i]`, `@v1[i]` are vectors; `@i1[i]` and `@r1[current]` are
//! empty), `device_output_missing.sp` (an empty one stops `write`: "no writable vector found",
//! F13).
//!
//! Contents: `pub(super) fn readable(letter: u8, name: &str) -> bool`

use std::collections::HashMap;
use std::sync::OnceLock;

/// Whether an element of card letter `letter` (lowercase) has an output vector `name`.
pub(super) fn readable(letter: u8, name: &str) -> bool {
    let devices: &[&str] = match letter {
        b'r' => &["res"],
        b'c' => &["cap"],
        b'l' => &["ind"],
        b'v' => &["vsrc"],
        b'i' => &["isrc"],
        b'e' => &["vcvs"],
        b'f' => &["cccs"],
        b'g' => &["vccs"],
        b'h' => &["ccvs"],
        b'b' => &["asrc"],
        b'd' => &["dio", "numd", "numd2"],
        b's' => &["sw"],
        b'w' => &["csw"],
        b't' => &["tra"],
        b'o' => &["ltra"],
        b'u' => &["urc"],
        b'y' => &["txl"],
        b'p' => &["cpl"],
        b'q' => &["bjt", "vbic", "hicum2", "nbjt", "nbjt2"],
        b'j' => &["jfet", "jfet2"],
        b'z' => &["mes", "mesa", "hfet1", "hfet2"],
        b'm' => &[
            "mos1",
            "mos2",
            "mos3",
            "mos6",
            "mos9",
            "bsim1",
            "bsim2",
            "bsim3",
            "bsim3v0",
            "bsim3v1",
            "bsim3v32",
            "bsim4",
            "bsim4v5",
            "bsim4v6",
            "bsim4v7",
            "bsim3soi_dd",
            "bsim3soi_fd",
            "bsim3soi_pd",
            "bsimsoi",
            "soi3",
            "hisim2",
            "hisimhv1",
            "hisimhv2",
            "vdmos",
            "numos",
        ],
        _ => return true,
    };
    let name = name.to_ascii_lowercase();
    devices.iter().any(|d| {
        table()
            .get(d)
            .is_some_and(|names| names.binary_search(&name.as_str()).is_ok())
    })
}

// ---- private ----

/// `outputs.txt` as sorted name lists per device, read once.
fn table() -> &'static HashMap<&'static str, Vec<&'static str>> {
    static TABLE: OnceLock<HashMap<&'static str, Vec<&'static str>>> = OnceLock::new();
    TABLE.get_or_init(|| {
        include_str!("families/outputs.txt")
            .lines()
            .filter(|l| !l.starts_with('#'))
            .map(|l| {
                let mut words = l.split(' ');
                let device = words.next().expect("a device key");
                let mut names: Vec<&str> = words.collect();
                names.sort_unstable();
                (device, names)
            })
            .collect()
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn the_settled_outputs_are_the_tables() {
        // Oracle: settle device_outputs.sp (59-long vectors and empty ones)
        for (letter, name, has) in [
            (b'i', "c", true),
            (b'i', "current", true),
            (b'i', "i", false),
            (b'r', "i", true),
            (b'r', "current", false),
            (b'v', "i", true),
        ] {
            assert_eq!(
                super::readable(letter, name),
                has,
                "@{}[{name}]",
                letter as char
            );
        }
    }
}
